// Official Minecraft Java Edition glyph_sizes.bin (65,536 bytes)
// Packs (startColumn << 4) | endColumn for all Unicode BMP codepoints (U+0000 to U+FFFF)
const B64_DATA = '';

let cachedSizes: Uint8Array | null = null;

export function getMinecraftGlyphSizes(): Uint8Array {
  if (!cachedSizes) {
    const binary = atob(B64_DATA);
    const len = binary.length;
    cachedSizes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      cachedSizes[i] = binary.charCodeAt(i);
    }
  }
  return cachedSizes;
}
